const config = {
  crmBaseUrl: 'https://TU-CRM.example.com',
  sourceId: 'REEMPLAZAR_CON_ID_DE_FUENTE',
  googleSheetUrl: 'https://docs.google.com/spreadsheets/d/REEMPLAZAR/edit',
  sheetName: 'Inventario',
  batchSize: 500,
};
return [{ json: config }];

const config = $('CONFIGURACION - EDITAR').first().json;
const clean = (value) => String(value ?? '').trim();
const key = (value) => clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const parseTiers = (value, rowNumber) => {
  const source = clean(value);
  if (!source) return [];
  if (source.startsWith('[')) {
    try {
      const parsed = JSON.parse(source);
      if (!Array.isArray(parsed)) throw new Error();
      return parsed;
    } catch {
      throw new Error(`Fila ${rowNumber}: Rangos de precio contiene JSON invalido.`);
    }
  }
  return source.split('|').map((part, index) => {
    const match = part.trim().match(/^(\d+)\s*(?:(?:-\s*(\d+))|(\+))\s*[:=]\s*\$?\s*([\d,.]+)$/);
    if (!match) throw new Error(`Fila ${rowNumber}: rango ${index + 1} invalido. Usa 100-150:70|151+:67.`);
    return { minQuantity: match[1], maxQuantity: match[3] ? null : match[2], unitPrice: match[4] };
  });
};
if (!clean(config.crmBaseUrl).startsWith('https://') || clean(config.crmBaseUrl).includes('TU-CRM')) throw new Error('Edita crmBaseUrl en CONFIGURACION - EDITAR.');
if (!clean(config.sourceId) || clean(config.sourceId).startsWith('REEMPLAZAR')) throw new Error('Edita sourceId en CONFIGURACION - EDITAR.');
const rawRows = $input.all().map((item) => item.json).filter((row) => row && Object.keys(row).length > 0);
if (!rawRows.length) throw new Error('La hoja esta vacia. Por seguridad no se inicio la conciliacion.');
const rows = rawRows.map((raw, index) => {
  const row = Object.fromEntries(Object.entries(raw).map(([name, value]) => [key(name), value]));
  const rowNumber = index + 2;
  const sku = clean(row.sku || row.codigo || row.codigo_producto || row.id_producto);
  const name = clean(row.nombre || row.producto || row.nombre_producto);
  if (!sku || !name) throw new Error(`Fila ${rowNumber}: SKU y Nombre son obligatorios.`);
  return {
    sku,
    name,
    category: row.categoria ?? row.category ?? '',
    description: row.descripcion ?? row.description ?? '',
    brand: row.marca ?? row.brand ?? '',
    unit: row.unidad ?? row.unit ?? 'pieza',
    salePrice: row.precio ?? row.precio_venta ?? row.sale_price ?? '',
    priceTiers: parseTiers(row.rangos_de_precio ?? row.precios_por_cantidad ?? row.price_tiers, rowNumber),
    internalCost: row.costo ?? row.costo_interno ?? row.internal_cost ?? '',
    tags: row.etiquetas ?? row.tags ?? '',
    imageUrl: row.imagen ?? row.image_url ?? '',
    location: row.ubicacion ?? row.location ?? 'Principal',
    onHand: row.existencia ?? row.stock ?? row.inventario ?? row.on_hand ?? 0,
    reserved: row.reservado ?? row.reserved ?? 0,
    minimumStock: row.minimo ?? row.stock_minimo ?? row.minimum_stock ?? 0,
    isActive: row.activo ?? row.active ?? true,
    sourceUpdatedAt: row.actualizado_en ?? row.source_updated_at ?? '',
  };
});
const batchSize = Math.min(500, Math.max(1, Number(config.batchSize) || 500));
return [{ json: { ...config, crmBaseUrl: clean(config.crmBaseUrl).replace(/\/$/, ''), rows, batchSize, idempotencyKey: `google-sheets-${clean(config.sourceId)}-${Date.now()}` } }];

const context = $('Validar y normalizar hoja').first().json;
const runId = $input.first().json.runId;
if (!runId) throw new Error('El CRM no devolvio runId.');
const output = [];
for (let index = 0; index < context.rows.length; index += context.batchSize) {
  output.push({ json: { crmBaseUrl: context.crmBaseUrl, runId, rows: context.rows.slice(index, index + context.batchSize), batchNumber: output.length + 1 } });
}
return output;

const responses = $input.all().map((item) => item.json);
const failures = responses.filter((response) => typeof response.accepted !== 'number' || (Array.isArray(response.rejected) && response.rejected.length > 0));
const details = failures.flatMap((response) => Array.isArray(response.rejected) ? response.rejected : [response.error?.message || response.message || 'Un lote no fue aceptado por el CRM.']);
return [{ json: { ok: failures.length === 0, error: details.join(' | ').slice(0, 1000), runId: $('CRM - Iniciar conciliacion').first().json.runId, crmBaseUrl: $('Validar y normalizar hoja').first().json.crmBaseUrl, batches: responses.length } }];
